      time.sleep(1)
      
      # Fill email and password
      self.safe_send_keys((By.XPATH, "//input[@placeholder='name@example.com' or @type='email']"), "alex.owner@autodoc.com")
      self.safe_send_keys((By.XPATH, "//input[@type='password']"), "autodocowner2026")
      time.sleep(0.5)

      # Click Sign In submit button on login screen
