    # 2. Navigate to "Service Centers" tab (labeled as 'Workshops' in nav bar or 'Find Service Center' on home screen)
    self.safe_click((By.XPATH, "//*[text()='Workshops' or text()='Find Service Center' or contains(text(),'Service Centers') or contains(text(),'Partners')]"))
    time.sleep(1)

    # 3. Click "Book Service" button on first service center card
    self.safe_click((By.XPATH, "(//*[contains(text(),'Book Service')])[1]"))
