    # 5. Click "Submit Service Request" button in modal
    self.safe_click((By.XPATH, "//*[contains(text(),'Submit Service Request') or contains(text(),'Confirm Service Booking')]"))

    # 6. Verify confirmation
    wait = WebDriverWait(self.driver, 15)
    confirmation = wait.until(
      EC.presence_of_element_located((By.XPATH, "//*[contains(text(),'successfully sent') or contains(text(),'Booking Request Sent') or contains(text(),'submitted') or contains(text(),'Partners & Service Centers') or contains(text(),'Workshops')]"))
    )
    assert confirmation is not None, "Service booking failed or confirmation message not displayed."


  
